SELECT  FROM t_cluster_link WHERE feedback_source_id IN
#{id}
ORDER BY feedback_source_id, id

SELECT  FROM t_cluster_link WHERE feedback_source_id IN
#{id}
ORDER BY feedback_source_id, id FOR UPDATE

SELECT  FROM t_cluster_link WHERE cluster_id IN
#{id}
AND relation_role = 'MAIN' AND is_active = 1 AND id > #{afterLinkId}
ORDER BY id LIMIT #{limit}

SELECT feedback_source_id, MIN(review_priority) priority, MIN(review_due_at) due_at, MIN(created_at) created_at FROM t_cluster_link WHERE relation_role = 'CANDIDATE' AND is_active = 1 AND review_status = 'PENDING' AND review_priority = #{priority} GROUP BY feedback_source_id
HAVING (FIELD(MIN(review_priority),'P1','P2','P3') > FIELD(#{afterPriority},'P1','P2','P3') OR (FIELD(MIN(review_priority),'P1','P2','P3') = FIELD(#{afterPriority},'P1','P2','P3') AND MIN(review_due_at) > #{afterDueAt}) OR (FIELD(MIN(review_priority),'P1','P2','P3') = FIELD(#{afterPriority},'P1','P2','P3') AND MIN(review_due_at) = #{afterDueAt} AND feedback_source_id > #{afterSourceId}))
ORDER BY FIELD(MIN(review_priority),'P1','P2','P3'), MIN(review_due_at), feedback_source_id LIMIT #{limit}

SELECT DISTINCT cluster_id FROM t_cluster_link
WHERE problem_fingerprint = #{fingerprint} AND relation_role = 'MAIN' AND is_active = 1
ORDER BY cluster_id LIMIT #{limit}

mapper.update:
UPDATE t_cluster_link SET is_active = 0, review_status = 'REJECTED', reviewed_by = CASE id
  WHEN #{row.linkId} THEN #{row.reviewerId}
  ELSE reviewed_by END,
  reviewed_at = NOW(3), review_reason = CASE id
  WHEN #{row.linkId} THEN #{row.reason}
  ELSE review_reason END,
  review_request_id = CASE id
  WHEN #{row.linkId} THEN #{row.requestId}
  ELSE review_request_id END,
  decision_reason = CASE id
  WHEN #{row.linkId} THEN #{row.decisionReason}
  ELSE decision_reason END,
  review_version = review_version + 1
WHERE is_active = 1 AND relation_role = 'MAIN' AND (

  (id = #{row.linkId} AND review_version = #{row.expectedVersion})
)

UPDATE t_cluster_link SET problem_fingerprint = #{fingerprint}
WHERE feedback_source_id = #{sourceId} AND cluster_id = #{clusterId}
  AND relation_role = 'MAIN' AND is_active = 1
